import { execSync } from 'node:child_process';
import { mkdtempSync, rmSync, mkdirSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { tmpdir } from 'node:os';

import { describe, it, expect, beforeEach, afterEach, vi } from 'vitest';

import YAML from 'yaml';

import { handleTest } from '../commands/test.js';

/**
 * Crea un repo Git real y aislado con dos módulos QAP registrados
 * (checkout y auth), cada uno con su repo-map.json, un commit base,
 * y luego modifica solo el archivo de 'checkout' sin commitear.
 */
function setupRepoWithTwoModules(): string {
  const rootDir = mkdtempSync(join(tmpdir(), 'qap-from-diff-test-'));

  execSync('git init -b main', { cwd: rootDir });
  execSync('git config user.email "test@qap.local"', { cwd: rootDir });
  execSync('git config user.name "QAP Test"', { cwd: rootDir });

  mkdirSync(join(rootDir, 'src', 'checkout'), { recursive: true });
  writeFileSync(join(rootDir, 'src', 'checkout', 'cart.ts'), 'export const cart = 1;\n');
  mkdirSync(join(rootDir, 'src', 'auth'), { recursive: true });
  writeFileSync(join(rootDir, 'src', 'auth', 'login.ts'), 'export const login = 1;\n');

  mkdirSync(join(rootDir, '.qa', 'modules', 'checkout', 'tests'), { recursive: true });
  writeFileSync(
    join(rootDir, '.qa', 'modules', 'checkout', 'context.yaml'),
    YAML.stringify({ _version: '2', module: 'checkout' })
  );
  writeFileSync(
    join(rootDir, '.qa', 'modules', 'checkout', 'repo-map.json'),
    JSON.stringify({ _version: '1', module: 'checkout', files: ['src/checkout/cart.ts'] })
  );

  mkdirSync(join(rootDir, '.qa', 'modules', 'auth', 'tests'), { recursive: true });
  writeFileSync(
    join(rootDir, '.qa', 'modules', 'auth', 'context.yaml'),
    YAML.stringify({ _version: '2', module: 'auth' })
  );
  writeFileSync(
    join(rootDir, '.qa', 'modules', 'auth', 'repo-map.json'),
    JSON.stringify({ _version: '1', module: 'auth', files: ['src/auth/login.ts'] })
  );

  execSync('git add .', { cwd: rootDir });
  execSync('git commit -m "base"', { cwd: rootDir });

  // Modifica solo 'checkout' sin commitear: solo ese módulo debe quedar afectado.
  writeFileSync(join(rootDir, 'src', 'checkout', 'cart.ts'), 'export const cart = 2;\n');

  return rootDir;
}

describe('qap test --from-diff (S75-002)', () => {
  let rootDir: string;
  let originalCwd: string;
  let logSpy: ReturnType<typeof vi.spyOn>;

  beforeEach(() => {
    rootDir = setupRepoWithTwoModules();
    originalCwd = process.cwd();
    process.chdir(rootDir);
    logSpy = vi.spyOn(console, 'log').mockImplementation(() => {});
  });

  afterEach(() => {
    process.chdir(originalCwd);
    rmSync(rootDir, { recursive: true, force: true });
    logSpy.mockRestore();
    vi.restoreAllMocks();
  });

  it('acota la ejecución solo al módulo afectado por el cambio de Git', async () => {
    await handleTest(undefined, { fromDiff: true });

        const logs: string[] = logSpy.mock.calls.map((call: unknown[]) => String(call[0]));
    const scopingLog = logs.find((line: string) => line.includes('--from-diff'));

    expect(scopingLog).toContain('checkout');
    expect(scopingLog).not.toContain('auth');
  });

  it('termina limpio con exit code 0 si ningún módulo fue afectado', async () => {
    // Revertimos el cambio sin commitear: ya no hay nada afectado.
    execSync('git checkout -- .', { cwd: rootDir });

    await handleTest(undefined, { fromDiff: true });

    expect(process.exitCode).toBe(0);
  });

  it('con un módulo explícito, solo corre si está entre los afectados (intersección)', async () => {
    // 'auth' no fue modificado, así que pedirlo explícitamente con --from-diff
    // debe dar como resultado "nada que ejecutar", no forzar su ejecución.
    await handleTest('auth', { fromDiff: true });

    const logs: string[] = logSpy.mock.calls.map((call: unknown[]) => String(call[0]));
    const noAffectedLog = logs.find(
      (line: string) => line.includes('Nada que ejecutar') || line.includes('no hay módulos afectados')
    );

    expect(noAffectedLog).toBeDefined();
  });
});

/**
 * Routing de subcomandos del CLI `qap`.
 *
 * Cada entrada mapea 1:1 con una operación pública de `QAPEngine`
 * (@qap/engine): discover, plan, test, update, report, status, context y
 * runFlow. En esta etapa solo se resuelve el *routing* y el parseo de sus
 * argumentos posicionales; el wiring real con `@qap/engine` se conecta en
 * un ticket posterior, por lo que cada acción lanza `NotImplementedError`.
 *
 * Añadir un subcomando nuevo consiste en agregar una entrada a `COMMANDS`;
 * `registerCommands` se encarga de darlo de alta en el árbol de Commander.
 */

/**
 * Routing de subcomandos del CLI `qap`.
 */

import type { Command } from 'commander';

import { NotImplementedError } from './errors.js';
import { handleClean } from './commands/clean.js';
import { handleAuthAdd, handleAuthList, handleAuthSetSecret, handleAuthRemove } from './commands/auth/index.js';
import { handleRun } from './commands/runner/index.js';
import { handleStatus } from './commands/status/index.js';
import { handleContext } from './commands/context.js';
import { handleSearch } from './commands/search.js';
import { handleConfigShow, handleConfigSet } from './commands/config/index.js';
import { handleDiscover } from './commands/discover.js';
import { handleReport } from './commands/report.js';
import { handleInitCommand } from './commands/init.js';
import { handleValidate } from './commands/validate.js';
import { handlePrune } from './commands/prune.js';
import { handleRuntimeReindex } from './commands/reindex.js';
import { handlePlan } from './commands/plan.js';
import { handleMcp, handleMcpRegister } from './commands/mcp.js';
import { handleTest } from './commands/test.js';
import { handleUpdate } from './commands/update.js';
import { handleRollback } from './commands/rollback.js';

export { handleClean } from './commands/clean.js';
export { handleMcp } from './commands/mcp.js';

interface CommandDefinition {
  /** Nombre del subcomando, p.ej. "test" -> `qap test`. */
  name: string;
  description: string;
  /** Argumentos posicionales en sintaxis Commander, p.ej. "<module>". */
  args?: string;
}

// Mantenemos únicamente los stubs pendientes que aún no tienen implementación real
const COMMANDS: readonly CommandDefinition[] = [
  { name: 'flow', description: 'Ejecuta un flow definido sobre uno o más módulos.', args: '<flow>' },
];

export function registerCommands(program: Command): void {
  // 1. Registrar el comando `init`
  program
    .command('init')
    .description('Inicializa la estructura .qa/ en el proyecto actual')
    .option('-c, --config <path>', 'Ruta al archivo JSON de configuración para modo silencioso')
    .action(async (options: { config?: string }) => {
      await handleInitCommand(options);
    });

  // 1b. Subcomando 'plan'
  program
    .command('plan <module>')
    .description('Genera la matriz de pruebas del módulo calculando checksum de configuración.')
    .action(async (moduleName: string) => {
      await handlePlan(moduleName);
    });

  // 1.1 Registrar comando `clean` (con alias `reset`)
  program
    .command('clean')
    .alias('reset')
    .description('Elimina de forma segura todo el árbol .qa/ del proyecto actual y limpia locks remanentes')
    .option('-y, --yes', 'Confirma la eliminación sin solicitar confirmación interactiva')
    .option('-f, --force', 'Fuerza la eliminación inmediata de .qa/ y locks remanentes')
    .action(async (options: { yes?: boolean; force?: boolean }) => {
      await handleClean(options);
    });

  // 2. Grupo de subcomandos 'auth' (Tarea S2-003)
  const authGroup = program
    .command('auth')
    .description('Gestión de perfiles de autenticación y credenciales locales');

  authGroup
    .command('add [profile]')
    .description('Registra un nuevo perfil de autenticación')
    .option('-p, --profile <profile>', 'Nombre del perfil')
    .action(async (profileArg?: string, options?: { profile?: string }) => {
      const targetProfile = options?.profile || profileArg || 'default';
      await handleAuthAdd(targetProfile);
    });

  authGroup
    .command('list')
    .description('Lista perfiles configurados sin exponer secretos')
    .action(async () => {
      await handleAuthList();
    });

  authGroup
    .command('set-secret [profile] [secret]')
    .description('Almacena un secreto directamente en el llavero local')
    .option('-p, --profile <profile>', 'Nombre del perfil')
    .option('-s, --secret <secret>', 'Valor del secreto')
    .action(async (profileArg?: string, secretArg?: string, options?: { profile?: string; secret?: string }) => {
      const targetProfile = options?.profile || profileArg || 'default';
      const targetSecret = options?.secret || secretArg || '';
      await handleAuthSetSecret(targetProfile, targetSecret);
    });

  authGroup
    .command('remove [profile]')
    .description('Elimina un perfil del llavero local')
    .option('-p, --profile <profile>', 'Nombre del perfil')
    .action(async (profileArg?: string, options?: { profile?: string }) => {
      const targetProfile = options?.profile || profileArg || 'default';
      await handleAuthRemove(targetProfile);
    });

  // 3. Subcomando 'status' (Soporta módulo opcional para resumen visual)
  program
    .command('status [module]')
    .description('Muestra el estado del proyecto o de un módulo específico')
    .action(async (moduleName?: string) => {
      await handleStatus(moduleName);
    });

  // 3b. Subcomando 'context'
  program
    .command('context <module>')
    .description('Muestra el contexto de un módulo (rutas, reglas, variables)')
    .action(async (moduleName: string) => {
      await handleContext(moduleName);
    });

  // 3c. Subcomando 'search'
  program
    .command('search <query> [module]')
    .description('Busca selectores en los módulos mapeados')
    .action(async (query: string, moduleName?: string) => {
      await handleSearch(query, moduleName);
    });

  // 3d. Subcomando 'run' y grupo 'config'
  program
    .command('run [target]')
    .description('Ejecuta las pruebas especificadas o la suite completa')
    .option('-p, --profile <profile>', 'Perfil de autenticación a utilizar')
    .option('--headed', 'Ejecutar en modo con interfaz gráfica')
    .action(async (target?: string, options?: { profile?: string; headed?: boolean }) => {
      await handleRun(target, options);
    });

  program
    .command('test [module]')
    .description('Ejecuta pruebas filtrando por tags, caso individual o shard')
    .option('--tags <tags>', 'Lista de tags separados por coma (ej. smoke,regression)')
    .option('--case <caseId>', 'Ejecuta un unico caso por su id')
    .option('--shard <shard>', 'Particiona la ejecucion en formato "i/n" (ej. 1/3)')
    .option('--retries <n>', 'Numero de reintentos para casos fallidos')
    .option('--headed', 'Ejecuta con interfaz grafica visible')
    .option('--fail-fast', 'Detiene la ejecucion en el primer caso fallido')
    .option('--from-diff', 'Ejecuta solo los modulos afectados por cambios de Git respecto a la rama base')
    .option('--force-unlock', 'Libera forzadamente el lock del módulo (o todos) antes de ejecutar')
    .action(async (moduleArg: string | undefined, options: import('./commands/test.js').TestCommandOptions) => {
      await handleTest(moduleArg, options);
    });

  program 
    .command('discover [name]')
    .description('Descubre un módulo por fases: interview, navigate, repo-map')
    .option('--phase <phase>', 'Fase a ejecutar: interview | navigate | repo-map', 'interview')
    .option('--amend', 'Corrige campos específicos de un módulo ya documentado, sin re-escaneo')
    .action(async (name: string | undefined, options: { phase?: string; amend?: boolean }) => {
      await handleDiscover(name, options);
    });

    // Subcomando 'update'
  program
    .command('update [module]')
    .description('Actualiza un módulo con diff de selectores, respaldo previo y recálculo de hash')
    .option('-y, --yes', 'Aplica los cambios sin pedir confirmación')
    .option('--dry-run', 'Muestra el diff sin modificar archivos')
    .option('--force', 'Ignora la protección manually_edited: true')
    .action(async (moduleName?: string, options?: { yes?: boolean; dryRun?: boolean; force?: boolean }) => {
      await handleUpdate(moduleName, options);
    });

  // Subcomando 'rollback'
  program
    .command('rollback [module]')
    .description('Restaura módulos y planes a estados previos desde .qa/cache/backups/')
    .option('--to <id>', 'Identificador del respaldo a restaurar')
    .action(async (moduleName?: string, options?: { to?: string }) => {
      await handleRollback(moduleName, options);
    });

  const configGroup = program
    .command('config')
    .description('Gestiona la configuración del proyecto QA');

  configGroup
    .command('show')
    .description('Muestra la configuración activa')
    .action(async () => {
      await handleConfigShow();
    });

  configGroup
    .command('set <key> <value>')
    .description('Establece un valor de configuración')
    .action(async (key: string, value: string) => {
      await handleConfigSet(key, value);
    });

  // 4. Subcomandos 'report' y 'serve'
  program
    .command('report [module]')
    .description('Genera el reporte de resultados de un módulo o levanta el visor interactivo con --serve')
    .option('-s, --serve', 'Inicia el servidor web interactivo del Knowledge Graph y visor de memoria')
    .option('-p, --port <port>', 'Puerto en el que escuchará el servidor web (por defecto: 9280)', '9280')
    .option('-f, --format <format>', 'Formato de reporte estático: html')
    .action(async (moduleArg?: string, options?: { serve?: boolean; port?: string | number; format?: string }) => {
      await handleReport(moduleArg, options);
    });

  program
    .command('serve')
    .description('Inicia el servidor web interactivo del Knowledge Graph en http://localhost:9280')
    .option('-p, --port <port>', 'Puerto en el que escuchará el servidor web (por defecto: 9280)', '9280')
    .action(async (options?: { port?: string | number }) => {
      await handleReport(undefined, { ...options, serve: true });
    });

  // 5. Subcomando 'validate'
  program
    .command('validate [path]')
    .description('Valida estáticamente las definiciones (.qa/definitions/), schemas y ciclos del DAG')
    .action(async (targetPath?: string) => {
      await handleValidate(targetPath);
    });

  // 6. Subcomando 'prune'
  program
    .command('prune')
  .description('Elimina ejecuciones, capturas temporales y logs obsoletos')
  .option('--older-than-days <dias>', 'Antigüedad máxima en días')
  .option('--max-bytes <bytes>', 'Límite de cuota en disco')
  .option('--max-entries <entradas>', 'Número máximo de ejecuciones a conservar')
  .option('--dry-run', 'Audita sin eliminar ningún archivo')
  .action(async (options) => {
    await handlePrune(options);
  });

  // 7. Grupo 'runtime' con 'reindex'
  const runtimeGroup = program
    .command('runtime')
    .description('Gestión del almacenamiento runtime local');

  runtimeGroup
    .command('reindex [dir]')
    .description('Reconstruye íntegramente la base de datos qap.sqlite desde run.json')
    .action(async (dir?: string) => {
      await handleRuntimeReindex(dir);
    });

     // 7.1. Subcomando 'mcp' para iniciar el servidor MCP sobre Stdio
  const mcpCmd = program
    .command('mcp')
    .description('Inicia el servidor MCP de QAP sobre transporte Stdio para Cursor, Claude y Antigravity')
    .option('--project <dir>', 'Directorio raíz del proyecto sobre el que opera el servidor')
    .action(async (options: { project?: string }) => {
      await handleMcp(options);
    });

  mcpCmd
    .command('register')
    .description('Registra el proyecto actual como servidor MCP en Cursor y/o Claude Desktop')
    .option('--client <client>', 'Cliente objetivo: cursor, claude o all', 'all')
    .option('--dry-run', 'Muestra la configuración propuesta sin modificar archivos')
    .action(async (options: { client?: string; dryRun?: boolean }) => {
      await handleMcpRegister(options);
    });

  // 8. Registrar los comandos placeholders restantes
  for (const definition of COMMANDS) {
    const subcommand = program.command(definition.name).description(definition.description);

    if (definition.args) {
      subcommand.arguments(definition.args);
    }

    subcommand.action(() => {
      throw new NotImplementedError(definition.name);
    });
  }
}

