/**
 * Storage Mock — S3-001 (QAP v2.1)
 *
 * Provides a full Vitest mock of IStorage for use in engine unit tests.
 * Every method returns a sensible default resolved value so tests can
 * selectively override only what they need with `.mockResolvedValueOnce()`.
 *
 * Usage:
 *   import { createStorageMock } from './mocks/storage.mock.js';
 *   const mockStorage = createStorageMock();
 *   mockStorage.exists.mockResolvedValueOnce(true);
 */

import { vi } from 'vitest';

import type { IStorage } from '../../ports.js';

/**
 * Full mock of IStorage with typed vi.fn() for every method.
 * The shape { [K in keyof IStorage]: ReturnType<typeof vi.fn> } is intentionally
 * preserved so engine.test.ts can continue its existing mock patterns unchanged.
 */
export type StorageMock = { [K in keyof IStorage]: ReturnType<typeof vi.fn> };

/**
 * Creates a fresh StorageMock with default resolved values.
 * Call this in beforeEach() to avoid state leakage between tests.
 */
export function createStorageMock(): StorageMock {
  return {
    // --- Low-level primitives ---
    read: vi.fn().mockResolvedValue(''),
    write: vi.fn().mockResolvedValue(undefined),
    exists: vi.fn().mockResolvedValue(false),
    list: vi.fn().mockResolvedValue([]),
    delete: vi.fn().mockResolvedValue(undefined),
    mkdir: vi.fn().mockResolvedValue(undefined),
    readJson: vi.fn().mockResolvedValue({}),
    writeJson: vi.fn().mockResolvedValue(undefined),

    // --- Global project configuration ---
    getProjectRoot: vi.fn().mockReturnValue('/fake/project/root'),
    isInitialized: vi.fn().mockResolvedValue(false),
    getEnvironments: vi.fn().mockResolvedValue({
      _version: '2.1.0',
      environments: {},
      default: 'dev',
    }),
    saveEnvironments: vi.fn().mockResolvedValue(undefined),
    getProjectContext: vi.fn().mockResolvedValue({
      _version: '2.1.0',
      project_name: 'test-project',
    }),
    saveProjectContext: vi.fn().mockResolvedValue(undefined),
    getSystemPrompt: vi.fn().mockResolvedValue(null),
    getLifecycleState: vi.fn().mockResolvedValue({
      _version: '1',
      phase: 'ONBOARDING',
      session: { id: '', started_at: '', plan: [] },
      modules: {},
      history: [],
    }),
    saveLifecycleState: vi.fn().mockResolvedValue(undefined),
    updateLifecycleState: vi.fn().mockImplementation(async (mutator: (state: any) => any) => {
      const current = {
        _version: '1',
        phase: 'ONBOARDING',
        session: { id: '', started_at: '', plan: [] },
        modules: {},
        history: [],
      };
      return await mutator(current);
    }),

    // --- Module domain ---
    listModules: vi.fn().mockResolvedValue([]),
    hasModule: vi.fn().mockResolvedValue(false),
    getModuleContext: vi.fn().mockResolvedValue({
      _version: '2.1.0',
      objective: '',
      manually_edited: false,
      routes: [],
    }),
    saveModuleContext: vi.fn().mockResolvedValue(undefined),
    getModuleRules: vi.fn().mockResolvedValue(null),
    saveModuleRules: vi.fn().mockResolvedValue(undefined),
    getModulePrereqs: vi.fn().mockResolvedValue(null),
    saveModulePrereqs: vi.fn().mockResolvedValue(undefined),
    getModuleSelectors: vi.fn().mockResolvedValue({ selectors: {} }),
    saveModuleSelectors: vi.fn().mockResolvedValue(undefined),
    getSemanticHash: vi.fn().mockResolvedValue(null),
    saveSemanticHash: vi.fn().mockResolvedValue(undefined),

    // --- Test plans and test cases ---
    getTestPlan: vi.fn().mockResolvedValue({ modules: [] }),
    saveTestPlan: vi.fn().mockResolvedValue(undefined),
    listTestCases: vi.fn().mockResolvedValue([]),
    getTestCase: vi.fn().mockResolvedValue(null),
    saveTestCase: vi.fn().mockResolvedValue(undefined),

    // --- Execution results and history ---
    saveExecutionResult: vi.fn().mockResolvedValue(undefined),
    getExecutionResult: vi.fn().mockResolvedValue(null),
    appendHistory: vi.fn().mockResolvedValue(undefined),

    // --- Multi-module flows ---
    listFlows: vi.fn().mockResolvedValue([]),
    getFlow: vi.fn().mockResolvedValue(null),
    saveFlow: vi.fn().mockResolvedValue(undefined),

    // --- Diagnostics ---
    getStatus: vi.fn().mockResolvedValue({
      initialized: false,
      modules_discovered: 0,
      environment_configured: false,
    }),
  };
}

import { describe, it, expect } from 'vitest';
import type { ProjectRepoMap, ProposedModuleCandidate } from '@qap/shared';

import { generateModuleCandidates } from '../candidate-generator.js';

describe('C4: generateModuleCandidates (Generador de Módulos Candidatos)', () => {
  // Mock o validador temporal si SchemaValidator requiere ajuste
  const validator = {
    validateModuleCandidates: (_candidatesFile: any) => ({ valid: true })
  };

  const docText = `
# Especificación del Sistema de Gestión

Este documento describe los módulos del sistema.

## Módulo de Catálogo
El catálogo de productos permite ver ítems y precios.
Evidencia exacta: Catálogo de productos disponibles con filtros avanzados.

## Módulo de Checkout
El checkout procesa pagos y compras.
Evidencia: Procesamiento seguro de pagos y órdenes.

## Módulo de Reportes
Permite consultar balances contables.
Evidencia: Consulta de balances contables mensuales.
  `;

  const repoMap: ProjectRepoMap = {
    _version: '1.0.0',
    subproyectos: [{ path: 'web', name: 'web', framework: 'react' }],
    rutas: [
      {
        path: '/catalogo',
        archivo: 'src/pages/catalogo.tsx',
        linea: 1,
        framework: 'react',
        requiere_sesion: null,
        roles: [],
      },
      {
        path: '/checkout-pago',
        archivo: 'src/pages/checkout.tsx',
        linea: 1,
        framework: 'react',
        requiere_sesion: true,
        roles: [],
      },
      {
        path: '/ajustes',
        archivo: 'src/pages/ajustes.tsx',
        linea: 1,
        framework: 'react',
        requiere_sesion: true,
        roles: [],
      },
    ],
    advertencias: [],
  };

  const criticalFlows = [
    { name: 'Buscar producto' },
    { name: 'Pagar orden' },
    { name: 'Generar balance' },
  ];

  it('procesa candidato válido con ruta_hint exacta y le asigna confianza alta y fuentes doc+repo', () => {
    const proposed: ProposedModuleCandidate[] = [
      {
        nombre: 'Catálogo',
        ruta_hint: '/catalogo',
        evidence: 'Catálogo de productos disponibles con filtros avanzados.',
        flujos: ['Buscar producto'],
      },
    ];

    const res = generateModuleCandidates({
      rawDocContent: docText,
      proposedCandidates: proposed,
      repoMap,
      criticalFlows,
    });

    expect(res.rejectedCandidates).toHaveLength(0);
    const cand = res.candidatesFile.candidates.find((c: any) => c.nombre === 'Catálogo');
    expect(cand).toBeDefined();
    expect(cand?.ruta).toBe('/catalogo');
    expect(cand?.confianza).toBe('alta');
    expect(cand?.fuentes).toEqual(['doc', 'repo']);
    expect(cand?.flujos).toEqual(['Buscar producto']);

    const val = validator.validateModuleCandidates(res.candidatesFile);
    expect(val.valid).toBe(true);
  });

  it('asocia ruta por solapamiento de vocabulario >= 60% y asigna confianza media', () => {
    const proposed: ProposedModuleCandidate[] = [
      {
        nombre: 'Checkout Pago',
        evidence: 'Procesamiento seguro de pagos y órdenes.',
        flujos: ['Pagar orden'],
      },
    ];

    const res = generateModuleCandidates({
      rawDocContent: docText,
      proposedCandidates: proposed,
      repoMap,
      criticalFlows,
    });

