describe('LockManager (S75-005A)', () => {
  let tempDir: string;
  let lockManager: LockManager;

  beforeEach(() => {
    tempDir = fs.mkdtempSync(path.join(os.tmpdir(), 'qap-lock-test-'));
    lockManager = new LockManager({ rootDir: tempDir });
  });

  afterEach(() => {
    if (fs.existsSync(tempDir)) {
      fs.rmSync(tempDir, { recursive: true, force: true });
    }
  });

  it('debe adquirir y liberar un lock de módulo exitosamente', async () => {
    const release = await lockManager.acquireModuleLock('checkout');
    expect(typeof release).toBe('function');
    await release();
  });

  it('debe lanzar error "lock_timeout" si se intenta bloquear concurrentemente el mismo módulo', async () => {
    const release1 = await lockManager.acquireModuleLock('checkout');

    await expect(lockManager.acquireModuleLock('checkout')).rejects.toThrowError(/lock_timeout/);

    await release1();
  });

  it('debe permitir forceUnlock para limpiar locks forzadamente', async () => {
    await lockManager.acquireModuleLock('checkout');

    // Forzar liberación
    await lockManager.forceUnlock('checkout');

    // Ahora debería poder adquirirse de nuevo sin lanzar lock_timeout
    const release2 = await lockManager.acquireModuleLock('checkout');
    expect(typeof release2).toBe('function');
    await release2();
  });
  it('forceUnlock () sin argumento  debe liberar todos los locks activos', async() => {
    await lockManager.acquireModuleLock('checkout');
    await lockManager.acquireModuleLock('auth');

    await lockManager.forceUnlock();

    const releaseCheckout = await lockManager.acquireModuleLock('checkout');
    const releaseAuth = await lockManager.acquireModuleLock('auth');
    expect(typeof releaseCheckout).toBe ('function');
    expect(typeof releaseAuth).toBe('function');

    await releaseCheckout();
    await releaseAuth();
  });
});

import { existsSync, mkdirSync, writeFileSync, rmSync, readdirSync } from 'node:fs';
import { dirname, join } from 'node:path';
import lockfile from 'proper-lockfile';

export interface LockManagerOptions {
  rootDir?: string;
}

export class LockManager {
  private rootDir: string;
  private locksDir: string;

  constructor(options: LockManagerOptions = {}) {
    this.rootDir = options.rootDir ?? process.cwd();
    this.locksDir = join(this.rootDir, '.qa', 'cache', 'locks');
  }

  private getPaths(moduleName: string): { targetPath: string; lockfilePath: string } {
    const targetPath = join(this.locksDir, `${moduleName}.target`);
    const lockfilePath = join(this.locksDir, `${moduleName}.lock`);
    return { targetPath, lockfilePath };
  }

  /**
   * Bloquea por módulo creando un archivo centinela .target y fijando lockfilePath en .qa/cache/locks/
   */
  async acquireModuleLock(moduleName: string): Promise<() => Promise<void>> {
    if (!existsSync(this.locksDir)) {
      mkdirSync(this.locksDir, { recursive: true });
    }

    const { targetPath, lockfilePath } = this.getPaths(moduleName);

    if (!existsSync(targetPath)) {
      mkdirSync(dirname(targetPath), { recursive: true });
      writeFileSync(targetPath, '', 'utf-8');
    }

    try {
      const release = await lockfile.lock(targetPath, {
        retries: 0,
        stale: 30000,
        update: 5000,
        lockfilePath,
      });

      return async () => {
        try {
          await release();
        } catch {
          // Ignorar si ya fue liberado
        }
      };
    } catch (err: unknown) {
      const msg = err instanceof Error ? err.message : String(err);
      throw new Error(`lock_timeout: El módulo '${moduleName}' se encuentra bloqueado por otro proceso (${msg}).`);
    }
  }

  /**
   * Implementa forceUnlock(moduleName?) eliminando los .lock y archivos asociados en .qa/cache/locks/
   */
    async forceUnlock(moduleName?: string): Promise<void> {
    if (moduleName) {
      this.removeLockFiles(moduleName);
      return;
    }

    // Sin moduleName: libera todos los locks activos en .qa/cache/locks/.
    if (!existsSync(this.locksDir)) {
      return;
    }

    const lockFiles = readdirSync(this.locksDir).filter((f) => f.endsWith('.target'));
    for (const file of lockFiles) {
      const name = file.slice(0, -'.target'.length);
      this.removeLockFiles(name);
    }
  }

  private removeLockFiles(moduleName: string): void {
    const { targetPath, lockfilePath } = this.getPaths(moduleName);
    try {
      if (existsSync(lockfilePath)) {
        rmSync(lockfilePath, { recursive: true, force: true });
      }
      if (existsSync(targetPath)) {
        rmSync(targetPath, { force: true });
      }
    } catch {
      // Ignorar errores de limpieza forzada
    }
  }
}

