import { createHash } from 'node:crypto';

import type { IKnowledgeStore, KnowledgeRecord } from '@qap/engine';
import {
  validateExpectedRequirement,
  validateCoverageAssessmentInvariants,
  type CanonicalCoverageAssessment,
  type CanonicalGap,
  type CategoryApplicabilityDecision,
  type CategorySpecificationStatus,
  type ExecutionCoverageSummary,
  type ExpectedRequirement,
  type RequirementCategory,
  type ReviewCoverage,
  type SpecificationCoverage,
  type CanonicalClosureVerdict,
} from '@qap/shared';

import { ModuleObservationBridge, type BridgeContext } from './module-observation-bridge.js';
import type { IModuleClosureStore } from './module-closure-store.js';

const FORMAL_CATEGORIES: readonly RequirementCategory[] = [
  'functional',
  'business_rule',
  'security',
  'ui',
  'ux',
  'regression',
  'performance',
] as const;

const digest = (value: unknown): string =>
  createHash('sha256').update(JSON.stringify(value)).digest('hex');

export interface CoverageEvaluationOptions {
  readonly applicabilityDecisions?: readonly CategoryApplicabilityDecision[];
  readonly acceptedGaps?: readonly { readonly gap_id: string; readonly reason: string }[];
  readonly isWaived?: boolean;
  readonly waiverReason?: string;
  readonly decisionId?: string;
  /** Read-only replay comparison: temporarily restore named accepted gaps to pending. */
  readonly excludeStoredAcceptedGapIds?: readonly string[];
}

export type CoverageEvaluationResult =
  | { readonly status: 'evaluated'; readonly assessment: CanonicalCoverageAssessment }
  | { readonly status: 'blocked'; readonly code: string; readonly razon: string };

/**
 * Servicio de Cobertura Canónica (R1 / R2).
 * Evalúa cobertura usando exclusivamente información legítima:
 * - Identidad canónica del módulo validada contra el estado canónico (ModuleObservationBridge).
 * - Requisitos confirmados vigentes que superen Invariante D-011 y R1 (validateExpectedRequirement).
 * - Criterios de aceptación y decisiones autoritativas de aplicabilidad.
 * - Cero cobertura acreditada por crawler, elementos DOM, códigos HTTP 200 o archivos YAML no validados.
 * - Cobertura de ejecución estrictamente 'not_executed' (cero ConformityAssessment.pass).
 */
export class CanonicalCoverageService {
  private readonly bridge: ModuleObservationBridge;
  private readonly context: BridgeContext;

  constructor(
    private readonly store: IKnowledgeStore,
    context: BridgeContext,
    private readonly closureStore?: IModuleClosureStore
  ) {
    this.context = structuredClone(context);
    this.bridge = new ModuleObservationBridge(store, this.context);
  }

  async evaluate(
    plannedName: string,
    options?: CoverageEvaluationOptions
  ): Promise<CoverageEvaluationResult> {
    const resolution = await this.bridge.resolve(plannedName);
    if (resolution.status !== 'resolved') {
      return {
        status: 'blocked',
        code: resolution.status,
        razon: `El módulo '${plannedName}' no pudo resolverse canónicamente: ${resolution.status}`,
      };
    }

    const app = this.context.applicationId;
    const link = resolution.link;

    // 1. Cargar conocimiento histórico de cierre desde closureStore si está disponible
    const closureSnapshot = this.closureStore?.read({
      projectRoot: this.context.projectRoot,
      applicationId: app,
      environmentId: this.context.environmentId,
    });

    const storedDecisions = closureSnapshot?.applicabilityDecisions[plannedName] ?? [];
    const storedGaps = closureSnapshot?.acceptedGaps[plannedName] ?? [];

    // Combinar decisiones de aplicabilidad (opciones en tiempo de ejecución tienen precedencia sobre persistidas)
    const applicabilityMap = new Map<RequirementCategory, CategoryApplicabilityDecision>();
    for (const d of storedDecisions) {
      applicabilityMap.set(d.category, d);
    }
    if (options?.applicabilityDecisions) {
      for (const d of options.applicabilityDecisions) {
        applicabilityMap.set(d.category, d);
      }
    }

    // Combinar brechas aceptadas
    const acceptedGapsMap = new Map<string, { reason: string; receipt?: string }>();
    const excludedForReplay = new Set(options?.excludeStoredAcceptedGapIds ?? []);
    for (const g of storedGaps) {
      if (g.status === 'accepted' && !excludedForReplay.has(g.id)) {
        acceptedGapsMap.set(g.id, { reason: g.reason, receipt: g.acceptance_receipt });
      }
    }
    if (options?.acceptedGaps) {
      for (const ag of options.acceptedGaps) {
        acceptedGapsMap.set(ag.gap_id, { reason: ag.reason, receipt: options.decisionId });
      }
    }

    // 2. Consultar requisitos canónicos del módulo en IKnowledgeStore
    const confirmedRequirements: KnowledgeRecord<'requirement'>[] = [];
    const pendingRequirements: KnowledgeRecord<'requirement'>[] = [];

    let cursor: string | undefined;
    let scanned = 0;
    do {
      const page = await this.store.query(app, 'requirement', {
        limit: 100,
        ...(cursor ? { cursor } : {}),
      });

      for (const req of page.items) {
        const ent = req.entity as ExpectedRequirement;
        if (
          ent.module_key === link.moduleKey &&
          ent.is_active === true &&
          !ent.superseded_by
        ) {
          // Filtrado riguroso de Invariantes D-011 y R1
          const status = ent.validation_status ?? ent.status;
          if (status === 'confirmed') {
            const validation = validateExpectedRequirement(ent);
            if (validation.valid) {
              // Validar que la procedencia no sea de observador/crawler/telemetría (D-011)
              const provenance = ent.provenance ?? ent.source;
              const isObservational =
                provenance === 'observed_telemetry' ||
                provenance === ('crawler' as unknown) ||
                provenance === ('active_probe' as unknown);

              if (!isObservational) {
                confirmedRequirements.push(req);
                continue;
              }
            }
          }
          pendingRequirements.push(req);
        }
      }

      scanned += page.items.length;
      cursor = page.next_cursor;
      if (cursor && scanned >= 1000) {
        return {
          status: 'blocked',
          code: 'inventory_limit',
          razon: `Límite de inventario excedido al consultar requisitos para el módulo '${plannedName}'.`,
        };
      }
    } while (cursor);

    // 3. Evaluar aplicabilidad y brechas por categoría
    const gaps: CanonicalGap[] = [];
    const categoryStatuses: CategorySpecificationStatus[] = [];
    const nowIso = new Date().toISOString();

    for (const cat of FORMAL_CATEGORIES) {
      const decision = applicabilityMap.get(cat);
      const catConfirmed = confirmedRequirements.filter(
        r => (r.entity as ExpectedRequirement).category === cat
      );
      const catPending = pendingRequirements.filter(
        r => (r.entity as ExpectedRequirement).category === cat
      );

      let applicability: 'applicable' | 'not_applicable' | 'unknown';
      if (decision) {
        applicability = decision.applicable ? 'applicable' : 'not_applicable';
      } else {
        applicability = catConfirmed.length > 0 ? 'applicable' : 'unknown';
      }

      const catGapIds: string[] = [];

      if (applicability === 'unknown') {
        const gapId = `gap:${link.moduleKey}:${cat}:unknown_applicability`;
        catGapIds.push(gapId);
        const acceptedInfo = acceptedGapsMap.get(gapId);
        gaps.push({
          id: gapId,
          module_key: link.moduleKey,
          category: cat,
          absence_type: acceptedInfo ? 'accepted_gap' : 'unknown_applicability',
          status: acceptedInfo ? 'accepted' : 'unaddressed',
          acceptance_receipt: acceptedInfo?.receipt,
          reason: acceptedInfo?.reason ?? `La aplicabilidad de la categoría '${cat}' no ha sido declarada autoritativamente.`,
          related_requirement_ids: [],
          provenance: 'canonical_coverage_evaluator',
          created_at: nowIso,
        });
      } else if (applicability === 'applicable') {
        if (catConfirmed.length === 0) {
          const gapId = `gap:${link.moduleKey}:${cat}:missing_specification`;
          catGapIds.push(gapId);
          const acceptedInfo = acceptedGapsMap.get(gapId);
          gaps.push({
            id: gapId,
            module_key: link.moduleKey,
            category: cat,
            absence_type: acceptedInfo ? 'accepted_gap' : 'missing_specification',
            status: acceptedInfo ? 'accepted' : 'unaddressed',
            acceptance_receipt: acceptedInfo?.receipt,
            reason: acceptedInfo?.reason ?? `La categoría '${cat}' es aplicable pero carece de requisitos confirmados vigentes.`,
            related_requirement_ids: [],
            provenance: 'canonical_coverage_evaluator',
            created_at: nowIso,
          });
        } else {
          // Requisitos confirmados pero con criterios incompletos
          for (const req of catConfirmed) {
            const ent = req.entity as ExpectedRequirement;
            if (!ent.acceptance_criteria || ent.acceptance_criteria.length === 0) {
              const gapId = `gap:${link.moduleKey}:${req.id}:incomplete_criteria`;
              catGapIds.push(gapId);
              const acceptedInfo = acceptedGapsMap.get(gapId);
              gaps.push({
                id: gapId,
                module_key: link.moduleKey,
                category: cat,
                absence_type: acceptedInfo ? 'accepted_gap' : 'incomplete_acceptance_criterion',
                status: acceptedInfo ? 'accepted' : 'unaddressed',
                acceptance_receipt: acceptedInfo?.receipt,
                reason: acceptedInfo?.reason ?? `El requisito confirmado '${ent.title}' carece de criterios de aceptación verificables.`,
                related_requirement_ids: [req.id],
                provenance: 'canonical_coverage_evaluator',
                created_at: nowIso,
              });
            }
          }
        }

        // Brechas por requisitos pendientes
        for (const req of catPending) {
          const ent = req.entity as ExpectedRequirement;
          const gapId = `gap:${link.moduleKey}:${req.id}:pending_requirement`;
          catGapIds.push(gapId);
          const acceptedInfo = acceptedGapsMap.get(gapId);
          gaps.push({
            id: gapId,
            module_key: link.moduleKey,
            category: cat,
            absence_type: acceptedInfo ? 'accepted_gap' : 'pending_requirement',
            status: acceptedInfo ? 'accepted' : 'unaddressed',
            acceptance_receipt: acceptedInfo?.receipt,
            reason: acceptedInfo?.reason ?? `El requisito '${ent.title}' está pendiente de confirmación autoritativa.`,
            related_requirement_ids: [req.id],
            provenance: 'canonical_coverage_evaluator',
            created_at: nowIso,
          });
        }
      }

      // Estado de la categoría
      let catStatus: 'satisfied' | 'gaps_present' | 'not_applicable' | 'unknown';
      if (applicability === 'not_applicable') {
        catStatus = 'not_applicable';
      } else if (applicability === 'unknown') {
        catStatus = 'unknown';
      } else {
        const catGaps = gaps.filter(g => catGapIds.includes(g.id));
        const hasUnaddressed = catGaps.some(g => g.status === 'unaddressed');
        if (!hasUnaddressed && catConfirmed.length > 0) {
          catStatus = 'satisfied';
        } else {
          catStatus = 'gaps_present';
        }
      }

      categoryStatuses.push({
        category: cat,
        applicability,
        confirmed_count: catConfirmed.length,
        pending_count: catPending.length,
        gap_ids: catGapIds,
        status: catStatus,
      });
    }

    // 4. Cobertura de Especificación
    const applicableCategories = categoryStatuses.filter(cs => cs.applicability === 'applicable');
    const satisfiedCategories = categoryStatuses.filter(cs => cs.status === 'satisfied');
    const unaddressedGaps = gaps.filter(g => g.status === 'unaddressed');
    const acceptedGapsList = gaps.filter(g => g.status === 'accepted');

    const isComplete =
      categoryStatuses.every(cs => cs.status === 'satisfied' || cs.status === 'not_applicable') &&
      unaddressedGaps.length === 0 &&
      pendingRequirements.length === 0;

    const specificationCoverage: SpecificationCoverage = {
      status: isComplete ? 'complete' : 'incomplete',
      applicable_categories_count: applicableCategories.length,
      satisfied_categories_count: satisfiedCategories.length,
      confirmed_requirements_count: confirmedRequirements.length,
      pending_requirements_count: pendingRequirements.length,
      total_gaps_count: gaps.length,
      unaddressed_gaps_count: unaddressedGaps.length,
      accepted_gaps_count: acceptedGapsList.length,
      category_statuses: categoryStatuses,
    };

    // 5. Cobertura de Revisión
    const reviewCoverage: ReviewCoverage = {
      status: applicabilityMap.size > 0 || acceptedGapsList.length > 0 ? 'reviewed' : 'pending_review',
      reviewed_questions_count: confirmedRequirements.length,
      pending_questions_count: pendingRequirements.length,
      decisions_count: applicabilityMap.size + acceptedGapsList.length,
      host_decisions: [
        ...Array.from(applicabilityMap.values()).map(d => d.decision_id),
        ...acceptedGapsList.map(g => g.acceptance_receipt).filter((r): r is string => Boolean(r)),
      ],
    };

    // 6. Cobertura de Ejecución (Estrictamente no ejecutada en R5)
    const executionCoverage: ExecutionCoverageSummary = {
      status: 'not_executed',
      executed_count: 0,
      passed_count: 0,
      failed_count: 0,
      indeterminate_count: 0,
      note: 'La cobertura de ejecución requiere ejecución con test runner (VNEXT-014). Cero certificación de ejecución en R5.',
    };

    // 7. Dictamen de Cierre y Bloqueadores
    const blockerReasons: string[] = [];
    let closureVerdict: CanonicalClosureVerdict;

    if (options?.isWaived) {
      closureVerdict = 'waived';
    } else if (categoryStatuses.some(cs => cs.applicability === 'unknown')) {
      closureVerdict = 'blocked_by_unknown_applicability';
      blockerReasons.push('Existen categorías cuya aplicabilidad no ha sido determinada autoritativamente.');
    } else if (unaddressedGaps.length > 0) {
      closureVerdict = 'blocked_by_gaps';
      blockerReasons.push(`Existen ${unaddressedGaps.length} brechas de cobertura no abordadas.`);
    } else if (pendingRequirements.length > 0) {
      closureVerdict = 'blocked_by_unconfirmed';
      blockerReasons.push(`Existen ${pendingRequirements.length} requisitos pendientes de confirmación.`);
    } else if (isComplete) {
      closureVerdict = 'ready_for_closure';
    } else {
      closureVerdict = 'blocked_by_gaps';
      blockerReasons.push('La especificación del módulo no está completa.');
    }

    // 8. Digest determinista inmutable
    const coverageDigest = digest([
      link.moduleId,
      link.moduleKey,
      link.moduleRevision,
      resolution.fingerprint,
      confirmedRequirements.map(r => [r.id, r.revision]).sort(),
      // Pending and rejected observational revisions must also invalidate a
      // previously reviewed snapshot, even in a non-applicable category.
      pendingRequirements.map(r => [r.id, r.revision]).sort(),
      categoryStatuses,
      gaps.map(g => [g.id, g.status, g.absence_type, g.acceptance_receipt]).sort(),
      // A retryable host review must be bound to the actual applicability
      // decision, not the transient clock time when the request was built.
      // Preserve decided_at in the assessment/store for audit, but do not
      // let a fresh timestamp invalidate an otherwise identical pending
      // request. Category, applicability, reason, reviewer and decision ID
      // remain part of the digest; requirement revisions and context are
      // independently bound above.
      Array.from(applicabilityMap.entries())
        .map(([category, decision]) => [category, decision.applicable, decision.reason,
          decision.decided_by, decision.decision_id])
        .sort((a, b) => String(a[0]).localeCompare(String(b[0]))),
    ]);

    const assessment: CanonicalCoverageAssessment = {
      module_key: link.moduleKey,
      module_id: link.moduleId,
      module_revision: link.moduleRevision,
      application_id: app,
      environment_id: this.context.environmentId,
      assessed_at: nowIso,
      assessed_by: 'canonical_coverage_service',
      coverage_digest: coverageDigest,
      specification_coverage: specificationCoverage,
      review_coverage: reviewCoverage,
      execution_coverage: executionCoverage,
      gaps,
      applicability_decisions: Array.from(applicabilityMap.values()),
      closure_verdict: closureVerdict,
      blocker_reasons: blockerReasons,
    };

    // Validar invariantes
    const validation = validateCoverageAssessmentInvariants(assessment);
    if (!validation.valid) {
      return {
        status: 'blocked',
        code: 'coverage_invariants_violated',
        razon: `Invariantes de cobertura violados: ${validation.violations.map(v => v.message).join('; ')}`,
      };
    }

    return {
      status: 'evaluated',
      assessment,
    };
  }
}

import { AsyncLocalStorage } from 'node:async_hooks';
import { createCipheriv, createDecipheriv, createHash, randomBytes } from 'node:crypto';
import { closeSync, existsSync, lstatSync, openSync, realpathSync } from 'node:fs';
import { createRequire } from 'node:module';
import { dirname, isAbsolute } from 'node:path';
import type { DatabaseSync } from 'node:sqlite';

import type { CanonicalGap, CategoryApplicabilityDecision, RequirementCategory } from '@qap/shared';

export interface ClosureScope {
  projectRoot: string;
  applicationId: string;
  environmentId: string;
}

export interface ModuleClosureRecord {
  readonly moduleKey: string;
  readonly moduleId: string;
  readonly moduleRevision: number;
  readonly plannedName: string;
  readonly status: 'closed' | 'waived';
  readonly decisionId: string;
  readonly reviewer: string;
  readonly decidedAt: string;
  readonly requestDigest: string;
  readonly coverageDigest: string;
  readonly waiverReason?: string;
  readonly acceptedGaps?: readonly { readonly gap_id: string; readonly reason: string }[];
  readonly nonApplicableCategories?: readonly { readonly category: RequirementCategory; readonly reason: string }[];
  readonly committedAt: string;
}

export interface ModuleClosureSnapshot {
  readonly scope: ClosureScope;
  readonly closures: Record<string, ModuleClosureRecord>;
  readonly applicabilityDecisions: Record<string, CategoryApplicabilityDecision[]>;
  readonly acceptedGaps: Record<string, CanonicalGap[]>;
  readonly approvals: Array<[string, string]>; // [decisionId, requestDigest]
}

export type ClosureStoreAvailability = 'compatible' | 'not_initialized' | 'incompatible' | 'corrupt' | 'unavailable';

export class ClosureStoreError extends Error {
  constructor(readonly code: ClosureStoreAvailability | 'conflict' | 'context_changed' | 'revision_conflict' | 'write_failed' | 'scope_mismatch' | 'retention_limit' | 'decision_reused' | 'authorization_expired') {
    super(`Module closure store: ${code}`);
  }
}

const commitDeadline = new AsyncLocalStorage<number>();

export function withClosureCommitDeadline<T>(deadlineMs: number, action: () => Promise<T>): Promise<T> {
  if (!Number.isFinite(deadlineMs)) throw new ClosureStoreError('authorization_expired');
  return commitDeadline.run(deadlineMs, action);
}

/**
 * Privileged host contract: SQL closure transaction must execute in the same
 * AsyncLocalStorage context as withClosureCommitDeadline. A wrapper/decorator
 * that queues work using timers/tasks created before the review request is
 * NOT an authorized host composition unless it explicitly propagates the ALS
 * context and rechecks the deadline before physical COMMIT.
 *
 * This interface is structurally typed and cannot enforce propagation at
 * runtime for arbitrary third-party decorators. The standard host composition
 * uses SqliteModuleClosureStore directly; do not claim a universal deadline
 * guarantee for arbitrary IModuleClosureStore implementations.
 */
export interface IModuleClosureStore {
  read(scope: ClosureScope): ModuleClosureSnapshot;
  transaction<T>(scope: ClosureScope, operation: (snapshot: ModuleClosureSnapshot) => Promise<T>): Promise<T>;
  close(): void;
}

export interface SqliteModuleClosureOptions extends ClosureScope {
  path: string;
  key: Uint8Array;
  initialize?: boolean;
  protection: 'host_private_directory_and_managed_key';
}

const hash = (value: unknown) => createHash('sha256').update(JSON.stringify(value)).digest('hex');

/**
 * Almacén durable de decisiones de cierre de módulos e historial de autorizaciones (R4).
 * Esquema v1 aislado en SQLite independiente del catálogo canónico, cifrado completo AES-256-GCM.
 */
export class SqliteModuleClosureStore implements IModuleClosureStore {
  private db?: DatabaseSync;
  private readonly key: Buffer;
  private readonly scope: string;
  private readonly identity: ClosureScope;
  private busy = false;
  private availability: ClosureStoreAvailability = 'unavailable';

  constructor(options: SqliteModuleClosureOptions) {
    this.key = Buffer.from(options.key);
    this.identity = { projectRoot: options.projectRoot, applicationId: options.applicationId, environmentId: options.environmentId };
    this.scope = hash([options.projectRoot, options.applicationId, options.environmentId]);

    if (
      this.key.length !== 32 ||
      options.protection !== 'host_private_directory_and_managed_key' ||
      !isAbsolute(options.path) ||
      !isAbsolute(options.projectRoot) ||
      !options.applicationId ||
      !options.environmentId
    ) {
      throw new ClosureStoreError('scope_mismatch');
    }

    try {
      if (realpathSync(options.projectRoot) !== options.projectRoot) throw new ClosureStoreError('scope_mismatch');
      if (realpathSync(dirname(options.path)) !== dirname(options.path)) throw new ClosureStoreError('scope_mismatch');

      if (options.initialize) {
        const fd = openSync(options.path, 'wx', 0o600);
        closeSync(fd);
      } else if (!existsSync(options.path)) {
        this.availability = 'not_initialized';
        return;
      }

      const stat = lstatSync(options.path);
      if (!stat.isFile() || stat.isSymbolicLink() || stat.nlink !== 1) throw new ClosureStoreError('scope_mismatch');

      const sqlite = createRequire(import.meta.url)('node:sqlite') as typeof import('node:sqlite');
      this.db = new sqlite.DatabaseSync(options.path);
      this.db.exec('PRAGMA busy_timeout=0');

      if (options.initialize) {
        this.db.exec(`BEGIN IMMEDIATE;
          CREATE TABLE closure_meta (version INTEGER NOT NULL, scope TEXT NOT NULL);
          CREATE TABLE closure_history (generation INTEGER PRIMARY KEY, payload BLOB NOT NULL);
          INSERT INTO closure_meta VALUES (1, '${this.scope}'); COMMIT;`);
      }

      const meta = this.db.prepare('SELECT version, scope FROM closure_meta').all() as Array<{ version: number; scope: string }>;
      if (meta.length !== 1 || meta[0].version !== 1) throw new ClosureStoreError('incompatible');
      if (meta[0].scope !== this.scope) throw new ClosureStoreError('scope_mismatch');

      this.db.prepare('SELECT generation, payload FROM closure_history LIMIT 0').all();
      this.db.exec('PRAGMA synchronous=FULL');
      this.availability = 'compatible';
      this.read(options);
      this.db.exec('PRAGMA journal_mode=WAL');
    } catch (error) {
      this.db?.close();
      this.db = undefined;
      const code = error && typeof error === 'object' && 'code' in error ? (error as { code: unknown }).code : undefined;
      const sqliteCode = error && typeof error === 'object' && 'errcode' in error ? (error as { errcode: unknown }).errcode : undefined;
      this.availability =
        (error instanceof ClosureStoreError && error.code === 'corrupt') || sqliteCode === 11 || sqliteCode === 26
          ? 'corrupt'
          : code === 'EACCES' || code === 'EPERM' || code === 'ENOENT'
          ? 'unavailable'
          : 'incompatible';
      if (options.initialize) throw new ClosureStoreError(this.availability);
    }
  }

  close(): void {
    if (this.busy) throw new ClosureStoreError('conflict');
    this.db?.close();
    this.db = undefined;
    this.key.fill(0);
    this.availability = 'unavailable';
  }

  private check(scope: ClosureScope): DatabaseSync {
    if (hash([scope.projectRoot, scope.applicationId, scope.environmentId]) !== this.scope) throw new ClosureStoreError('scope_mismatch');
    if (this.busy) throw new ClosureStoreError('conflict');
    if (!this.db || this.availability !== 'compatible') throw new ClosureStoreError(this.availability);
    return this.db;
  }

  private decode(payload: Uint8Array, generation: number): ModuleClosureSnapshot {
    try {
      const bytes = Buffer.from(payload);
      const decipher = createDecipheriv('aes-256-gcm', this.key, bytes.subarray(0, 12));
      decipher.setAAD(Buffer.from(`${this.scope}:${generation}`));
      decipher.setAuthTag(bytes.subarray(12, 28));
      const snapshot = JSON.parse(
        Buffer.concat([decipher.update(bytes.subarray(28)), decipher.final()]).toString()
      ) as ModuleClosureSnapshot;

      if (
        !snapshot.scope ||
        hash([snapshot.scope.projectRoot, snapshot.scope.applicationId, snapshot.scope.environmentId]) !== this.scope ||
        !snapshot.closures ||
        typeof snapshot.closures !== 'object' ||
        !Array.isArray(snapshot.approvals) ||
        snapshot.approvals.some(a => !Array.isArray(a) || a.length !== 2 || a.some(v => typeof v !== 'string'))
      ) {
        throw new Error();
      }
      return snapshot;
    } catch {
      throw new ClosureStoreError('corrupt');
    }
  }

  private latest(db: DatabaseSync) {
    const row = db.prepare('SELECT generation, payload FROM closure_history ORDER BY generation DESC LIMIT 1').get() as
      | { generation: number; payload: Uint8Array }
      | undefined;
    return {
      generation: row ? Number(row.generation) : 0,
      snapshot: row
        ? this.decode(row.payload, Number(row.generation))
        : {
            scope: structuredClone(this.identity),
            closures: {},
            applicabilityDecisions: {},
            acceptedGaps: {},
            approvals: [],
          },
    };
  }

  read(scope: ClosureScope): ModuleClosureSnapshot {
    try {
      return this.latest(this.check(scope)).snapshot;
    } catch (error) {
      throw error instanceof ClosureStoreError ? error : new ClosureStoreError('unavailable');
    }
  }

  async transaction<T>(scope: ClosureScope, operation: (snapshot: ModuleClosureSnapshot) => Promise<T>): Promise<T> {
    const db = this.check(scope);
    try {
      db.exec('BEGIN IMMEDIATE');
    } catch {
      throw new ClosureStoreError('conflict');
    }
    this.busy = true;
    try {
      const { snapshot, generation } = this.latest(db);
      const before = JSON.stringify(snapshot);
      const result = await operation(snapshot);
      const deadline = commitDeadline.getStore();
      if (deadline !== undefined && Date.now() >= deadline) throw new ClosureStoreError('authorization_expired');
      if (JSON.stringify(snapshot) !== before) {
        if (generation >= 4096) throw new ClosureStoreError('retention_limit');
        const nonce = randomBytes(12);
        const cipher = createCipheriv('aes-256-gcm', this.key, nonce);
        cipher.setAAD(Buffer.from(`${this.scope}:${generation + 1}`));
        const ciphertext = Buffer.concat([cipher.update(JSON.stringify(snapshot)), cipher.final()]);
        const payload = Buffer.concat([nonce, cipher.getAuthTag(), ciphertext]);
        db.prepare('INSERT INTO closure_history(generation, payload) VALUES (?, ?)').run(generation + 1, payload);
      }
      if (deadline !== undefined && Date.now() >= deadline) throw new ClosureStoreError('authorization_expired');
      db.exec('COMMIT');
      return result;
    } catch (error) {
      try {
        db.exec('ROLLBACK');
      } catch {
        this.availability = 'unavailable';
      }
      throw error instanceof ClosureStoreError ? error : new ClosureStoreError('write_failed');
    } finally {
      this.busy = false;
    }
  }
}

import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import { SessionStore } from '@qap/auth';
import { resolveModuleSession } from '../src/session-resolver.js';

describe('session-resolver (S75-006A)', () => {
  let tempDir: string;

  beforeEach(() => {
    tempDir = fs.mkdtempSync(path.join(os.tmpdir(), 'qap-session-test-'));

    // Configurar estructura .qa/modules/checkout/prereqs.yaml
    const moduleDir = path.join(tempDir, '.qa', 'modules', 'checkout');
    fs.mkdirSync(moduleDir, { recursive: true });
    fs.writeFileSync(
      path.join(moduleDir, 'prereqs.yaml'),
      'requires:\n  auth:\n    primary: "admin-user"\n'
    );
  });

  afterEach(() => {
    if (fs.existsSync(tempDir)) {
      fs.rmSync(tempDir, { recursive: true, force: true });
    }
    vi.restoreAllMocks();
  });

  it('debe retornar null si el módulo no requiere autenticación', async () => {
    const session = await resolveModuleSession(tempDir, 'non-existing-module');
    expect(session).toBeNull();
  });

  it('debe recuperar y descifrar una sesión válida guardada en el SessionStore (AES-256-GCM)', async () => {
    const sessionStore = new SessionStore(undefined, tempDir);
    const mockState = {
      cookies: [{ name: 'auth_token', value: 'secret', domain: 'example.com', path: '/', expires: Date.now() / 1000 + 3600, httpOnly: true, secure: true, sameSite: 'Lax' as const }],
      origins: []
    };

    sessionStore.saveSession('admin-user', mockState);

    const session = await resolveModuleSession(tempDir, 'checkout');
    expect(session).not.toBeNull();
    expect(session?.cookies[0].value).toBe('secret');
  });

  it('debe detectar sesión expirada y descartarla', async () => {
    const sessionStore = new SessionStore(undefined, tempDir);
    const expiredState = {
      cookies: [{ name: 'auth_token', value: 'expired', domain: 'example.com', path: '/', expires: Date.now() / 1000 - 3600, httpOnly: true, secure: true, sameSite: 'Lax' as const }],
      origins: []
    };

    sessionStore.saveSession('admin-user', expiredState);

    // Como expiró y no hay credenciales/perfil real configurado para hacer re-login en el mock, se espera error de perfil
    await expect(resolveModuleSession(tempDir, 'checkout')).rejects.toThrow(/Perfil de autenticación 'admin-user' no encontrado/);
  });
    it('ante sesión expirada, ejecuta re-login automático (login_mode: auto) y guarda la nueva sesión', async () => {
    const authDir = path.join(tempDir, '.qa', 'project', 'auth');
    fs.mkdirSync(authDir, { recursive: true });
    fs.writeFileSync(
      path.join(authDir, 'profiles.json'),
      JSON.stringify({
        profiles: [
          {
            id: 'admin-user',
            env: 'staging',
            username: 'admin',
            credential_source: 'env',
            env_var: 'QAP_TEST_PASSWORD',
            login_mode: 'auto',
            login_route: '/login',
          },
        ],
      })
    );

    const sessionStore = new SessionStore(undefined, tempDir);
    const expiredState = {
      cookies: [
        {
          name: 'auth_token',
          value: 'expired',
          domain: 'example.com',
          path: '/',
          expires: Date.now() / 1000 - 3600,
          httpOnly: true,
          secure: true,
          sameSite: 'Lax' as const,
        },
      ],
      origins: [],
    };
    sessionStore.saveSession('admin-user', expiredState);

    const authModule = await import('@qap/auth');
    vi.spyOn(authModule.AuthManager.prototype, 'getCredentials').mockResolvedValue({
      username: 'admin',
      password: 'fake-password',
    });

    const freshState = {
      cookies: [
        {
          name: 'auth_token',
          value: 'fresh-token',
          domain: 'example.com',
          path: '/',
          expires: Date.now() / 1000 + 3600,
          httpOnly: true,
          secure: true,
          sameSite: 'Lax' as const,
        },
      ],
      origins: [],
    };
    vi.spyOn(authModule, 'executeAutoLogin').mockResolvedValue(freshState);

    const session = await resolveModuleSession(tempDir, 'checkout');

    expect(session).not.toBeNull();
    expect(session?.cookies[0].value).toBe('fresh-token');

    // Confirma que la nueva sesión se guardó para futuras llamadas (no solo se devolvió).
    const reloadedStore = new SessionStore(undefined, tempDir);
    const persisted = reloadedStore.getValidSession('admin-user');
    expect(persisted?.cookies[0].value).toBe('fresh-token');
  });
});

import { describe, it, expect } from 'vitest';
import {
  validateCanonicalClosureCommand,
  validateCanonicalGap,
  validateCategoryApplicabilityDecision,
  validateCoverageAssessmentInvariants,
} from '../../domain/index.js';
import type {
  CanonicalClosureCommand,
  CanonicalGap,
  CategoryApplicabilityDecision,
  CanonicalCoverageAssessment,
} from '../../domain/index.js';

describe('VNEXT-013-R5 / Canonical Coverage & Closure Domain Invariants', () => {
  describe('validateCanonicalClosureCommand', () => {
    it('accepts valid evaluate and close commands', () => {
      expect(validateCanonicalClosureCommand({ action: 'evaluate' }).valid).toBe(true);
      expect(validateCanonicalClosureCommand({ action: 'close' }).valid).toBe(true);
    });

    it('accepts valid waive command with substantive reason', () => {
      const cmd: CanonicalClosureCommand = {
        action: 'waive',
        reason: 'El módulo no será implementado en esta versión debido a cambio de alcance.',
      };
      const res = validateCanonicalClosureCommand(cmd);
      expect(res.valid).toBe(true);
    });

    it('rejects waive command with short reason (< 15 chars)', () => {
      const res = validateCanonicalClosureCommand({
        action: 'waive',
        reason: 'muy corto',
      });
      expect(res.valid).toBe(false);
      expect(res.violations.some(v => v.code === 'SUBSTANTIVE_WAIVER_REASON_REQUIRED')).toBe(true);
    });

    it('rejects client-injected authorization fields (approvalId / signature)', () => {
      const res = validateCanonicalClosureCommand({
        action: 'close',
        approvalId: 'forged_host_approval_123',
      });
      expect(res.valid).toBe(false);
      expect(res.violations.some(v => v.code === 'CLIENT_AUTHORIZATION_INJECTION_FORBIDDEN')).toBe(true);
    });

    it('accepts valid accept_gaps command with substantive reasons', () => {
      const cmd: CanonicalClosureCommand = {
        action: 'accept_gaps',
        accepted_gaps: [
          {
            gap_id: 'gap_auth_01',
            reason: 'El módulo utiliza SSO externo documentado y validado formalmente.',
          },
        ],
      };
      const res = validateCanonicalClosureCommand(cmd);
      expect(res.valid).toBe(true);
    });

    it('rejects accept_gaps with empty gaps array or short reasons', () => {
      expect(validateCanonicalClosureCommand({ action: 'accept_gaps', accepted_gaps: [] }).valid).toBe(false);
      const shortRes = validateCanonicalClosureCommand({
        action: 'accept_gaps',
        accepted_gaps: [{ gap_id: 'g1', reason: 'corto' }],
      });
      expect(shortRes.valid).toBe(false);
      expect(shortRes.violations.some(v => v.code === 'SUBSTANTIVE_GAP_ACCEPTANCE_REASON_REQUIRED')).toBe(true);
    });

    it('accepts valid declare_non_applicable command', () => {
      const cmd: CanonicalClosureCommand = {
        action: 'declare_non_applicable',
        decisions: [
          {
            category: 'performance',
            reason: 'Módulo puramente estático de solo lectura sin SLA de rendimiento estricto.',
          },
        ],
      };
      const res = validateCanonicalClosureCommand(cmd);
      expect(res.valid).toBe(true);
    });
  });

  describe('validateCanonicalGap', () => {
    it('accepts a valid unaddressed gap', () => {
      const gap: CanonicalGap = {
        id: 'gap:payments:missing_security',
        module_key: 'payments',
        category: 'security',
        absence_type: 'missing_specification',
        status: 'unaddressed',
        reason: 'No se encontraron reglas de seguridad confirmadas para procesamiento de tarjetas.',
        related_requirement_ids: [],
        provenance: 'canonical_coverage_evaluator',
        created_at: new Date().toISOString(),
      };
      expect(validateCanonicalGap(gap).valid).toBe(true);
    });

    it('enforces Amendment 5: accepted_gap absence_type must have status accepted and acceptance_receipt', () => {
      const invalidGap: CanonicalGap = {
        id: 'gap:payments:accepted_01',
        module_key: 'payments',
        category: 'security',
        absence_type: 'accepted_gap',
        status: 'unaddressed', // Mismatch!
        reason: 'Brecha aceptada sin recibo de aprobación del host.',
        related_requirement_ids: [],
        provenance: 'canonical_coverage_evaluator',
        created_at: new Date().toISOString(),
      };
      const res = validateCanonicalGap(invalidGap);
      expect(res.valid).toBe(false);
      expect(res.violations.some(v => v.code === 'ACCEPTED_GAP_STATUS_MISMATCH')).toBe(true);
      expect(res.violations.some(v => v.code === 'ACCEPTED_GAP_RECEIPT_REQUIRED')).toBe(true);
    });

    it('accepts an accepted gap with valid receipt and status', () => {
      const validAcceptedGap: CanonicalGap = {
        id: 'gap:payments:accepted_01',
        module_key: 'payments',
        category: 'security',
        absence_type: 'accepted_gap',
        status: 'accepted',
        acceptance_receipt: 'decision_host_appr_998',
        reason: 'Riesgo residual aceptado por el responsable de seguridad para este release.',
        related_requirement_ids: [],
        provenance: 'canonical_coverage_evaluator',
        created_at: new Date().toISOString(),
      };
      expect(validateCanonicalGap(validAcceptedGap).valid).toBe(true);
    });
  });

  describe('validateCategoryApplicabilityDecision', () => {
    it('accepts a valid applicability decision', () => {
      const dec: CategoryApplicabilityDecision = {
        category: 'regression',
        applicable: false,
        reason: 'Nuevo módulo sin versiones previas contra las cuales comparar regresiones.',
        decided_by: 'lead_architect',
        decision_id: 'dec_appr_882',
        decided_at: new Date().toISOString(),
      };
      expect(validateCategoryApplicabilityDecision(dec).valid).toBe(true);
    });

    it('rejects short reasons (< 15 chars)', () => {
      const res = validateCategoryApplicabilityDecision({
        category: 'regression',
        applicable: false,
        reason: 'no aplica',
        decided_by: 'host',
        decision_id: 'dec_1',
        decided_at: new Date().toISOString(),
      });
      expect(res.valid).toBe(false);
      expect(res.violations.some(v => v.code === 'SUBSTANTIVE_APPLICABILITY_REASON_REQUIRED')).toBe(true);
    });
  });

  describe('validateCoverageAssessmentInvariants', () => {
    const baseAssessment: CanonicalCoverageAssessment = {
      module_key: 'checkout',
      module_id: 'mod_checkout_01',
      module_revision: 1,
      application_id: 'app_main',
      environment_id: 'env_staging',
      assessed_at: new Date().toISOString(),
      assessed_by: 'canonical_coverage_service',
      coverage_digest: 'a'.repeat(64),
      specification_coverage: {
        status: 'complete',
        applicable_categories_count: 2,
        satisfied_categories_count: 2,
        confirmed_requirements_count: 5,
        pending_requirements_count: 0,
        total_gaps_count: 1,
        unaddressed_gaps_count: 0,
        accepted_gaps_count: 1,
        category_statuses: [
          {
            category: 'functional',
            applicability: 'applicable',
            confirmed_count: 5,
            pending_count: 0,
            gap_ids: [],
            status: 'satisfied',
          },
          {
            category: 'security',
            applicability: 'applicable',
            confirmed_count: 0,
            pending_count: 0,
            gap_ids: ['gap_sec_accepted'],
            status: 'satisfied',
          },
        ],
      },
      review_coverage: {
        status: 'reviewed',
        reviewed_questions_count: 4,
        pending_questions_count: 0,
        decisions_count: 1,
        host_decisions: ['dec_host_1'],
      },
      execution_coverage: {
        status: 'not_executed',
        executed_count: 0,
        passed_count: 0,
        failed_count: 0,
        indeterminate_count: 0,
        note: 'Execution coverage requires test runner execution (VNEXT-014).',
      },
      gaps: [
        {
          id: 'gap_sec_accepted',
          module_key: 'checkout',
          category: 'security',
          absence_type: 'accepted_gap',
          status: 'accepted',
          acceptance_receipt: 'dec_host_1',
          reason: 'Brecha aceptada formalmente con mitigación en capa perimetral WAF.',
          related_requirement_ids: [],
          provenance: 'canonical_coverage_evaluator',
          created_at: new Date().toISOString(),
        },
      ],
      applicability_decisions: [],
      closure_verdict: 'ready_for_closure',
      blocker_reasons: [],
    };

    it('accepts a valid CanonicalCoverageAssessment ready for closure', () => {
      const res = validateCoverageAssessmentInvariants(baseAssessment);
      expect(res.valid).toBe(true);
    });

    it('strictly prohibits fake execution coverage or pass verdicts (Mandato de Integridad)', () => {
